package com.paymentalarm.app;
import android.app.*;import android.content.*;import android.media.*;import android.net.Uri;import android.os.*;
public class RingService extends Service {
 static final String CHANNEL="payment_alarm_ring";MediaPlayer player;int activeId=-1;
 @Override public void onCreate(){super.onCreate();NotificationChannel ch=new NotificationChannel(CHANNEL,"Payment alarm ringing",NotificationManager.IMPORTANCE_HIGH);ch.setSound(null,null);ch.setLockscreenVisibility(Notification.VISIBILITY_PUBLIC);((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).createNotificationChannel(ch);}
 @Override public int onStartCommand(Intent intent,int flags,int startId){if(intent!=null&&"STOP".equals(intent.getAction())){stopSelf();return START_NOT_STICKY;}activeId=intent==null?-1:intent.getIntExtra("id",-1);org.json.JSONObject x=AlarmStore.find(this,activeId);String title=x==null?"PAYMENT DUE":x.optString("name","PAYMENT DUE");String content=x==null?"Tap to stop alarm":"RM "+x.optString("amount")+" — "+x.optString("note");Intent screen=new Intent(this,AlarmActivity.class).putExtra("id",activeId).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_SINGLE_TOP);PendingIntent full=PendingIntent.getActivity(this,activeId,screen,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);Intent stop=new Intent(this,RingService.class).setAction("STOP");PendingIntent stopPi=PendingIntent.getService(this,activeId,stop,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);
 Notification n=new Notification.Builder(this,CHANNEL).setSmallIcon(android.R.drawable.ic_lock_idle_alarm).setContentTitle(title).setContentText(content).setCategory(Notification.CATEGORY_ALARM).setPriority(Notification.PRIORITY_MAX).setVisibility(Notification.VISIBILITY_PUBLIC).setOngoing(true).setFullScreenIntent(full,true).setContentIntent(full).addAction(new Notification.Action.Builder(android.R.drawable.ic_menu_close_clear_cancel,"STOP ALARM",stopPi).build()).build();startForeground(777,n);
 try{Uri uri=RingtoneManager.getDefaultUri(RingtoneManager.TYPE_ALARM);if(uri==null)uri=RingtoneManager.getDefaultUri(RingtoneManager.TYPE_NOTIFICATION);player=new MediaPlayer();player.setDataSource(this,uri);player.setAudioAttributes(new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_ALARM).setContentType(AudioAttributes.CONTENT_TYPE_SONIFICATION).build());player.setLooping(true);player.prepare();player.start();}catch(Exception e){android.util.Log.e("PaymentAlarm","Ringtone failed",e);}return START_NOT_STICKY;}
 @Override public void onDestroy(){if(player!=null){try{player.stop();}catch(Exception ignored){}player.release();player=null;}super.onDestroy();}
 @Override public IBinder onBind(Intent i){return null;}
}
